// Ownership is decided from the event Google actually holds, never from text the
// model supplied. The old guard compared ref: inside a description the agent
// retyped, so passing your own booking's description with someone else's event
// id would have passed it.
const REQ = $('When Executed by Another Workflow').first().json;
const ev  = $input.first().json || {};
const me  = String(REQ.requester || '').trim();
const confirmed = REQ.confirmed === true || String(REQ.confirmed).toLowerCase() === 'true';

if (!confirmed) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_CONFIRMED',
    human:'Nothing was cancelled. Show the requester the booking you found, end that message with the line "Confirm to cancel.", and stop. Cancel it only after they reply approving it.' } }];
}
if (!ev.id) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_FOUND',
    human:'Nothing was cancelled - that booking no longer exists on the calendar. Tell the requester and offer to search again.' } }];
}

const desc = String(ev.description || '');
const ref  = desc.match(/ref:\s*([A-Za-z0-9]+)/);
const by   = desc.match(/Booked by:\s*([^|]+)/);
const who  = by ? by[1].trim() : '';
const title = ev.summary || '(no title)';

if (!ref) {
  return [{ json: { verdict:'REJECTED', reason:'NO_REFERENCE', title,
    human:'BLOCKED - "' + title + '" carries no booker reference, so it cannot be confirmed as theirs. It was made before booker tracking, or created directly in Google Calendar. Tell the requester it has to be cancelled in Google Calendar instead. Nothing was cancelled.' } }];
}
if (ref[1] !== me) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_YOURS', title, booked_by: who || null,
    human:'BLOCKED - "' + title + '" was booked by ' + (who || 'someone else') + '. Only the person who made a booking can cancel it. Tell the requester who to coordinate with and do not try again. Nothing was cancelled.' } }];
}
return [{ json: { verdict:'CLEAR', event_id: ev.id, title,
  start: (ev.start && (ev.start.dateTime || ev.start.date)) || '' } }];

const c = $('Check Ownership').first().json;
return [{ json: { status:'CANCELLED', event_id: c.event_id, title: c.title,
  human:'Cancelled "' + c.title + '".' } }];

const v = $input.first().json || {};
return [{ json: { status:'REJECTED', reason: v.reason || 'FAILED',
  human: v.human || 'Nothing was cancelled and the reason is unclear. Tell the requester it did not go through.' } }];
